vec4 effect(vec2 uv) {
  vec4 c = getColor(uv);
  float burst = smoothstep(0.55, 0.9, noise(vec2(uTime * 2.0, 1.0))) * uAmount;
  float st = hash(uv * vec2(640.0, 360.0) + floor(uTime * 30.0));
  vec3 col = mix(c.rgb, vec3(st), burst);
  col *= 1.0 - burst * 0.3 * step(0.5, fract(uv.y * 120.0));
  return vec4(col, getColor(uv).a);
}
